      {/* Add Next button here */}
    </div>
  );
};

export default Pagination;

import React, { useState } from 'react';

// Create the Pagination component here
const Pagination = () => {
  // Initialize currentPage state here
  const [currentPage, setCurrentPage] = useState<number>(1);

  // Initialize totalPages state here
  const [totalPages, setTotalPages] = useState<number>(10);

  // Define handlePrevious function here
  const handlePrevious = () => {
    setCurrentPage((prevPage) => Math.max(prevPage - 1, 1));
  };

  // Define handleNext function here
  const handleNext = () => {
    setCurrentPage((prevPage) => Math.min(prevPage + 1, totalPages));
  };

  return (
    <div>
      {/* Add Previous button here */}
      <button onClick={handlePrevious}>Previous</button>
      {/* Add span to display current page information here */}
      <span>Page {currentPage} of {totalPages}</span>
      {/* Add Next button here */}
      <button>Next</button>
    </div>
  );
};

export default Pagination;
